inline uint64_t Number(const char* raw){Require(raw);size_t end=0;auto value=std::stoull(raw,&end);Require(end==std::strlen(raw));return value;}
inline bool Equal(const char* raw,const std::string& text){return raw&&std::string(raw)==text;}
inline MySQLRequestResult Q(Database& db,const std::string& sql){auto r=db.QueryDatabase(sql,false);if(!r.Success())throw std::runtime_error("Property outcome SQL failed");return r;}
inline bool OptionalTable(Database& db,const std::string& table){auto r=Q(db,"SELECT engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='"+table+"'");if(!r.RowCount())return false;Require(r.RowCount()==1&&Equal(r.begin()[0],"InnoDB"));return true;}
